"use client"

import { useSelector, useDispatch } from "react-redux";
import { toggleTheme } from "../features/themes/themeSlice";

export default function Navbar() {
  const themeValue = useSelector((state) => state.theme.value);
  const dispatch = useDispatch();

  const navigations = ["Home", "About", "Projects", "Contacts"]

  return (
    <div className="w-full py-4 px-6 flex items-center justify-between mb-4 text-black">
        <h1 className="text-2xl font-bold uppercase">Danniel</h1>

       <ul className="flex items-center justify-center no-underline gap-6 font-medium font-xl">
            {
              navigations.map((item, index) => (
                <li key={index}>{item}</li>
              ))
            }
       </ul>

       <button onClick={() => themeValue === "light" ? dispatch(toggleTheme("dark")) : dispatch(toggleTheme("light"))} 
        className={`border-2 py-1 px-6 rounded-full ${mode !== "Light" ? "bg-black text-white" : "bg-white text-black"} duration-300`}>{mode}
       </button>
    </div>
  )
}
